class Solution {
public:
    int bestRotation(vector<int>& nums) {
        int n = nums.size();
        vector<int> diff(n + 1, 0);
        for (int j = 0; j < n; j++) {
            int v = nums[j];
            if (v <= j) {
                diff[0]++;
                diff[j - v + 1]--;
            }
            int l2 = j + 1;
            int r2 = min(n - 1, j + n - v);
            if (l2 <= r2) {
                diff[l2]++;
                diff[r2 + 1]--;
            }
        }
        int bestK = 0, bestScore = -1, score = 0;
        for (int k = 0; k < n; k++) {
            score += diff[k];
            if (score > bestScore) {
                bestScore = score;
                bestK = k;
            }
        }
        return bestK;
    }
};
